const escapeHTML=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let account={loading:true,user:null,error:''},aboutContent={name:'',history:'',concept:'Danish eyewear with magnetic click-ons. Change your lenses while keeping your favourite frame.',why:'Switch from everyday glasses to sun lenses with one magnetic click. Your optician helps you find the right frame and fit.',instagram:'https://www.instagram.com/dook_denmark/',linkedin:'https://www.linkedin.com/company/dook-denmark/',facebook:'https://www.facebook.com/profile.php?id=61572809430865'},priceData=null,adminData=null;
const isAdmin=()=>account.user?.role==='admin';
const canPrice=()=>['admin','approved'].includes(account.user?.role);
async function api(path,method='GET',data){const r=await fetch(path,{method,credentials:'same-origin',cache:'no-store',headers:method==='GET'?{}:{'Content-Type':'application/json'},body:data?JSON.stringify(data):undefined});let result;try{result=await r.json()}catch{throw new Error('This service is temporarily unavailable. Please try again.')}if(!r.ok)throw new Error(result.error||'Please try again.');return result}
const paragraphs=value=>escapeHTML(value).split(/\n\s*\n/).map(p=>`<p>${p.replace(/\n/g,'<br>')}</p>`).join('');
const signOut=()=>`<button class="text-link" type="button" data-logout>Sign out</button>`;
const loginForm=()=>`<form id="login-form"><label>Email<input name="email" type="email" autocomplete="email" required></label><label>Password<input name="password" type="password" autocomplete="current-password" required minlength="10"></label><button class="pill">Log in <span>↗</span></button><p class="form-status" role="status"></p></form><div class="button-row"><a class="text-link" href="#signup">Create an account</a><a class="text-link" href="#forgot-password">Forgot password?</a></div>`;
const signupForm=()=>`<form id="signup-form"><label>Email<input name="email" type="email" autocomplete="email" required></label><label>Password<input name="password" type="password" autocomplete="new-password" required minlength="10"></label><button class="pill">Create account <span>↗</span></button><p class="form-status" role="status"></p></form><p class="note">Already have an account? <a class="text-link" href="#login">Log in</a></p>`;
const forgotForm=()=>`<form id="forgot-form"><label>Email<input name="email" type="email" autocomplete="email" required></label><button class="pill">Send reset link <span>↗</span></button><p class="form-status" role="status"></p></form><p class="note"><a class="text-link" href="#login">Back to log in</a></p>`;
function aboutPage(){return renderTopbar('ABOUT DOOK')+`<section class="page-head"><h1>About DOOK.</h1>${isAdmin()?'<a class="pill outline" href="#admin-content">Edit our story ↗</a>':''}</section><section class="section about-layout"><div class="about-image"><img src="/assets/hero.webp" alt="The detail of a DOOK Havana frame"></div><div><span class="eyebrow">THE CONCEPT</span><h2>One frame. More options.</h2>${paragraphs(aboutContent.concept)}<a class="text-link" href="#collection">Discover the collection ↗</a></div></section>${aboutContent.name?`<section class="section story-row"><div><span class="eyebrow">THE NAME</span><h2>Why DOOK?</h2></div><div>${paragraphs(aboutContent.name)}</div></section>`:''}${aboutContent.history?`<section class="section story-row"><div><span class="eyebrow">OUR STORY</span><h2>Where it all began.</h2></div><div>${paragraphs(aboutContent.history)}</div></section>`:''}<section class="manifesto"><div><span class="eyebrow">WHY CHOOSE DOOK?</span><h2>Designed for<br>your everyday.</h2></div><div>${paragraphs(aboutContent.why)}</div></section><section class="section social-section"><h2>Follow DOOK.</h2><div class="social-links">${['instagram','linkedin','facebook'].filter(k=>aboutContent[k]).map(k=>`<a href="${escapeHTML(aboutContent[k])}" target="_blank" rel="noopener noreferrer">${{instagram:'Instagram',linkedin:'LinkedIn',facebook:'Facebook'}[k]} <span>↗</span></a>`).join('')}</div></section>`+footer()}
function loginPage(){let content;
 if(account.loading)content='<p role="status">Loading your account…</p>';
 else if(account.error)content=`<p role="alert">${escapeHTML(account.error)}</p><button class="pill" data-retry-account>Try again</button>`;
 else if(!account.user)content=location.hash==='#signup'?`<h2>Create your account.</h2><p>New retailer? Create an account, then request price access.</p>${signupForm()}`:location.hash==='#forgot-password'?`<h2>Reset your password.</h2><p>We’ll email you a link to choose a new password.</p>${forgotForm()}`:`<h2>Welcome back.</h2><p>For approved retailers only.</p>${loginForm()}`;
 else if(canPrice())content=`<span class="eyebrow">${isAdmin()?'DOOK ADMINISTRATION':'APPROVED OPTICAL PARTNER'}</span><h2>You’re signed in.</h2><p>${escapeHTML(account.user.email)}</p><div class="button-row"><a href="#partners" class="pill">View partner collection ↗</a>${isAdmin()?'<a class="pill outline" href="#admin">Administration</a>':''}${signOut()}</div>`;
 else if(account.user.role==='pending')content=`<h2>Thank you.</h2><p>Your request is awaiting DOOK’s approval. Prices become available here once your company has been approved.</p><p>${escapeHTML(account.user.email)}</p><div class="button-row"><button class="pill outline" data-retry-account>Check access</button>${signOut()}</div>`;
 else if(account.user.role==='revoked')content=`<h2>Contact DOOK.</h2><p>Your price access is currently inactive. Please contact us to review your account.</p><div class="button-row"><a class="pill" href="#contact">Contact DOOK</a>${signOut()}</div>`;
 else content=`<h2>Become a partner.</h2><p>Signed in as ${escapeHTML(account.user.email)}. Tell us about your company so we can approve your access.</p><form id="access-form"><label>Your name<input name="name" autocomplete="name" maxlength="200" required></label><label>Company / optical store<input name="company" autocomplete="organization" maxlength="200" required></label><button class="pill">Request price access ↗</button><p class="form-status" role="status"></p></form>${signOut()}`;
 return renderTopbar('B2B LOGIN')+`<section class="login-layout"><div><h1>B2B</h1><p>Retailer login.</p><img src="/assets/dook-bookmark.png" alt="" class="login-mark"></div><div class="login-card">${content}</div></section>`+footer()}
function priceSummary(id){return `<span class="trade-card-price" data-price-model="${escapeHTML(id)}"></span>`}
function partners(){
 if(!canPrice())return loginPage();
 let page=partnerCollection();
 const banner=`<div class="partner-account"><span>${escapeHTML(account.user.email)}</span><div class="button-row">${isAdmin()?'<a href="#admin">Administration ↗</a>':''}${signOut()}</div></div>`;
 const prices=priceData?.config.enabled?`<section class="section"><div class="section-title"><div><span class="eyebrow">FRAMES & DOOKS</span><h2>Your trade prices.</h2></div></div><p>${escapeHTML(priceData.config.currency)} · ${escapeHTML(priceData.config.tax)}</p><label class="price-search">Find a frame or DOOK<input id="price-search" type="search" placeholder="Model, item or colour…"></label><div id="price-results">${priceTable(priceData.prices)}</div></section>`:`<section class="section"><h2>Trade prices</h2><p>${isAdmin()?'Your imported price list is a draft. Review the list and activate it in Administration.':'Prices are being updated. Please contact DOOK for a quote.'}</p>${isAdmin()?'<a class="pill" href="#admin">Review price list ↗</a>':''}</section>`;
 return banner+page.replace(footer(),prices+footer());
}
function detailPriceHTML(){return '<div class="trade-price" aria-live="polite"></div>'}
function money(n){return new Intl.NumberFormat('en-GB',{style:'currency',currency:priceData?.config?.currency||'DKK'}).format(n)}
function refreshPrices(){
 document.querySelectorAll('[data-price-model]').forEach(el=>{el.textContent='';if(!canPrice()||!priceData||!priceData.config.enabled)return;const rows=priceData.prices.filter(r=>r.model===el.dataset.priceModel);if(rows.length)el.textContent=`From ${money(Math.min(...rows.map(r=>r.amount)))}`});
 const box=document.querySelector('.trade-price');if(!box)return;
 if(!canPrice()){box.innerHTML='';box.hidden=true;return}box.hidden=false;
 if(!priceData){box.textContent='Loading trade prices…';return}
 if(!priceData.config.enabled){box.innerHTML=isAdmin()?'<a href="#admin">Review and activate your price list ↗</a>':'Trade prices are being updated. Contact DOOK for a quote.';return}
 const p=products.find(p=>p.id===detailModel),v=p?.variants[variantIndex];if(!p||!v)return;
 const rows=priceData.prices.filter(r=>r.model===p.id&&r.colour===v.code);
 const values=[...new Set(rows.map(r=>r.amount))];let text=values.length?`${values.length>1?'From ':''}${money(Math.min(...values))}`:'Price on request';
 box.innerHTML=`<span class="eyebrow">YOUR TRADE PRICE</span><strong>${escapeHTML(text)}</strong><small>${escapeHTML(priceData.config.currency)} · ${escapeHTML(priceData.config.tax)}</small>`;
 if(lensIndex>=0){const lens=window.dookLenses[lensIndex],model=p.id==='A001'?'D01':p.id==='AN001'?'DN01':null;const code=['GN01-3','MI01','BR01-GR-2','BR01-3','CL01-AB','GY01-GR-2','GY01-3-PL','YE01-NV','CL01-AB+1,0','BL01-GR-1'][lensIndex];const clips=priceData.prices.filter(r=>r.model===model&&r.colour===code);box.innerHTML+=`<div class="clip-price">DOOK · ${escapeHTML(lens.name)}<b>${clips.length?'From '+money(Math.min(...clips.map(r=>r.amount))):'Price on request'}</b></div><small>Match the exact model and size in the partner price list.</small>`}
}
function adminPage(){if(!isAdmin())return loginPage();return renderTopbar('DOOK ADMINISTRATION')+`<section class="page-head"><span class="eyebrow">YOUR WEBSITE</span><h1>Indhold & adgang</h1><a href="#admin" class="text-link">← Administration</a><p>Edit your About DOOK page, approve partners and review prices.</p><div class="button-row"><a class="pill" href="#partners">Open partner shop ↗</a><a class="pill outline" href="#news-edit">Manage News ↗</a></div></section><section class="section admin-section"><h2>About DOOK</h2><form id="about-form">${[['name','Why is it called DOOK?'],['concept','The concept'],['history','Our history and background'],['why','Why choose DOOK?']].map(([key,label])=>`<label>${label}<textarea name="${key}" maxlength="8000" rows="5" placeholder="Write your explanation here…">${escapeHTML(aboutContent[key])}</textarea></label>`).join('')}<p class="note">Empty name and history fields stay hidden on the public page. Your text is saved for all visitors.</p><div class="social-fields">${['instagram','linkedin','facebook'].map(k=>`<label>${{instagram:'Instagram',linkedin:'LinkedIn',facebook:'Facebook'}[k]}<input type="url" name="${k}" value="${escapeHTML(aboutContent[k])}" placeholder="https://"></label>`).join('')}</div><div class="button-row"><button class="pill">Save About DOOK</button><a href="#about" class="text-link">View page ↗</a></div><p class="form-status" role="status"></p></form></section><section class="section admin-section"><h2>Partner access</h2><div id="partner-management">Loading partners…</div></section><section class="section admin-section"><h2>Trade prices</h2><p>Draft imported from the PurchasePrice column in FrameCatalog-V2-20260911(2).xlsx, updated 18 September 2026. Check the prices, currency and VAT before making them visible to approved partners.</p><form id="pricing-form"><div class="form-row"><label>Currency<select name="currency"><option>DKK</option><option>EUR</option></select></label><label>VAT<select name="tax"><option>excl. VAT</option><option>incl. VAT</option></select></label></div><label class="checkbox-label"><input name="enabled" type="checkbox"> I have checked the price list. Show it to approved partners.</label><button class="pill">Save price settings</button><p class="form-status" role="status"></p></form><div id="admin-price-list"></div></section>`+footer()}
function priceTable(rows){return `<div class="price-table-wrap"><table class="price-table"><thead><tr><th>Item</th><th>Description</th><th>Trade price</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${escapeHTML(r.sku)}</td><td>${escapeHTML(r.description)}</td><td>${money(r.amount)}</td></tr>`).join('')}</tbody></table></div>`}
function fillAdmin(){if(!isAdmin())return;const box=document.querySelector('#partner-management');if(box&&adminData){box.innerHTML=adminData.partners.length?adminData.partners.map(p=>`<div class="partner-row"><div><strong>${escapeHTML(p.company)}</strong><p>${escapeHTML(p.name)} · ${escapeHTML(p.email)}</p><span class="note">${escapeHTML(p.status)}</span></div><button class="pill outline" data-partner-id="${escapeHTML(p.user_id)}" data-partner-status="${p.status==='approved'?'revoked':'approved'}">${p.status==='approved'?'Revoke access':'Approve access'}</button></div>`).join(''):'<p>No partner requests yet.</p>';const f=document.querySelector('#pricing-form');f.elements.currency.value=adminData.config.currency;f.elements.tax.value=adminData.config.tax;f.elements.enabled.checked=adminData.config.enabled}
 const list=document.querySelector('#admin-price-list');if(list&&priceData)list.innerHTML=`<label class="price-search">Find a frame or DOOK<input id="price-search" type="search" placeholder="Model, item or colour…"></label><p class="note">${priceData.prices.length} items · ${escapeHTML(priceData.config.tax)} · ${priceData.config.enabled?'Visible to approved partners':'Draft — hidden from partners'}</p><div id="price-results">${priceTable(priceData.prices)}</div>`;
}
async function loadAccount(){try{account={loading:false,...await api('/api/me'),error:''};priceData=null;if(canPrice())priceData=await api('/api/prices');if(isAdmin())adminData=await api('/api/admin')}catch(e){account.loading=false;account.error=e.message}document.querySelector('.partner-link').innerHTML=`B2B <span>↗</span>`;document.querySelector('.partner-link').href='#partners';if(canPrice()&&location.hash==='#login')history.replaceState(null,'','#partners');if(['#login','#signup','#forgot-password','#partners','#admin','#selection','#about'].includes(location.hash)||location.hash.startsWith('#news-edit')||location.hash.startsWith('#admin'))render();else refreshPrices();if(isAdmin()&&!document.querySelector('[data-admin-nav]'))document.querySelector('nav').insertAdjacentHTML('beforeend','<a href="#admin" data-page="admin" data-admin-nav>Administration <span>↗</span></a>');if(canPrice())loadInventory();}
// Opening #activate/<token> or #reset-password/<token> by typing/pasting it into an
// already-open tab is a same-document hash change, not a fresh page load — handled here
// so both the initial boot (initializeB2B) and later navigation (app.js hashchange) work.
async function handleAuthLink(){
 const activation=location.hash.startsWith('#activate/')?location.hash.slice(10):null;
 const resetToken=location.hash.startsWith('#reset-password/')?location.hash.slice(16):null;
 if(!activation&&!resetToken)return false;
 await loadAccount();
 if(activation){try{await api('/api/activate-owner','POST',{token:activation});history.replaceState(null,'','#admin');await loadAccount()}catch(e){app.innerHTML=renderTopbar('ADMINISTRATION')+`<section class="section"><h1>Activate administration</h1><p role="alert">${escapeHTML(e.message)}</p><p>Log in to the owner’s account, then open the activation link again.</p><a class="pill" href="#login">Log in ↗</a></section>`}}
 else{app.innerHTML=renderTopbar('B2B LOGIN')+`<section class="login-layout"><div><h1>B2B</h1><p>Choose a new password.</p></div><div class="login-card"><form id="reset-form"><input type="hidden" name="token" value="${escapeHTML(resetToken)}"><label>New password<input name="password" type="password" autocomplete="new-password" required minlength="10"></label><button class="pill">Set new password <span>↗</span></button><p class="form-status" role="status"></p></form></div></section>`+footer()}
 return true;
}
async function initializeB2B(){
 try{aboutContent=(await api('/api/about')).content}catch{}
 if(await handleAuthLink())return;
 await loadAccount();
 if(location.hash==='#about')render();
}
document.addEventListener('submit',async e=>{
 if(!['about-form','access-form','pricing-form','login-form','signup-form','forgot-form','reset-form'].includes(e.target.id))return;e.preventDefault();const form=e.target,button=form.querySelector('button'),status=form.querySelector('.form-status'),f=new FormData(form);button.disabled=true;status.textContent='Saving…';
 try{if(form.id==='about-form'){const r=await api('/api/about','PUT',Object.fromEntries(f));aboutContent=r.content;status.textContent='Saved. Your About DOOK page is updated.'}
 else if(form.id==='access-form'){await api('/api/access-request','POST',Object.fromEntries(f));await loadAccount()}
 else if(form.id==='login-form'){await api('/api/login','POST',{email:f.get('email'),password:f.get('password')});await loadAccount()}
 else if(form.id==='signup-form'){await api('/api/signup','POST',{email:f.get('email'),password:f.get('password')});await loadAccount()}
 else if(form.id==='forgot-form'){await api('/api/request-password-reset','POST',{email:f.get('email')});status.textContent='If that email has an account, a reset link is on its way.'}
 else if(form.id==='reset-form'){await api('/api/reset-password','POST',{token:f.get('token'),password:f.get('password')});status.textContent='Password updated. You can now log in.';location.hash='login'}
 else{await api('/api/admin/pricing','PUT',{currency:f.get('currency'),tax:f.get('tax'),enabled:f.has('enabled')});priceData=await api('/api/prices');adminData.config=priceData.config;status.textContent='Price settings saved.';document.querySelector('#admin-price-list').innerHTML=priceTable(priceData.prices)}
 }catch(error){status.textContent=error.message}finally{button.disabled=false}
});
document.addEventListener('click',async e=>{if(e.target.closest('[data-retry-account]'))await loadAccount();if(e.target.closest('[data-logout]')){await api('/api/logout','POST',{});await loadAccount()}const b=e.target.closest('[data-partner-id]');if(b){b.disabled=true;try{await api('/api/admin/partner','PUT',{id:b.dataset.partnerId,status:b.dataset.partnerStatus});adminData=await api('/api/admin');fillAdmin()}catch(error){b.after(Object.assign(document.createElement('p'),{textContent:error.message}));b.disabled=false}}});
document.addEventListener('input',e=>{if(e.target.id==='price-search'){const q=e.target.value.toLowerCase();document.querySelector('#price-results').innerHTML=priceTable(priceData.prices.filter(p=>(p.sku+' '+p.description).toLowerCase().includes(q)))}});
